<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Sign in | FleetDesk</title>
<style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:#f3f6fb;color:#14243a;font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif}.card{width:min(100%,440px);padding:34px;background:#fff;border:1px solid #e3e9f2;border-radius:18px;box-shadow:0 18px 55px #1b365014}.brand{display:flex;align-items:center;gap:13px;margin-bottom:28px}.logo{display:grid;place-items:center;width:48px;height:48px;border-radius:14px;background:#3978d5;color:#fff;font-size:25px;font-weight:750}.brand b{display:block;font-size:22px}.brand small{color:#71829a;letter-spacing:.12em;font-size:10px}.eyebrow{margin:0;color:#3978d5;font-weight:700;font-size:11px;letter-spacing:.15em}h1{margin:5px 0 7px;font-size:27px}p{color:#71829a;margin:0 0 20px}label{display:block;margin:15px 0 6px;font-size:13px;font-weight:650}input{width:100%;height:46px;padding:0 13px;border:1px solid #d8e0ec;border-radius:9px;font:inherit}input:focus{outline:3px solid #3978d522;border-color:#3978d5}button,.google{width:100%;min-height:47px;margin-top:12px;border:0;border-radius:9px;background:#3978d5;color:#fff;font:inherit;font-weight:700;cursor:pointer;text-decoration:none;display:flex;align-items:center;justify-content:center}.google{gap:10px}.google-mark{width:20px;height:20px;background:#fff;color:#4285f4;border-radius:50%;font-weight:800;display:grid;place-items:center}.secondary{background:#fff;color:#34465d;border:1px solid #d8e0ec}button:disabled{opacity:.6;cursor:wait}#message{min-height:24px;margin-top:12px;color:#b42318;font-size:13px}#message.ok{color:#16805c}.foot{margin:20px 0 0;text-align:center;color:#8a98aa;font-size:12px}.divider{display:flex;align-items:center;gap:10px;margin:20px 0;color:#9aa6b5;font-size:12px}.divider:before,.divider:after{content:"";height:1px;background:#e8edf3;flex:1}[hidden]{display:none!important}
</style></head>
<body><main class="card"><div class="brand"><div class="logo">F</div><div><b>FleetDesk</b><small>FLEET MANAGEMENT</small></div></div><p class="eyebrow">PRIVATE WORKSPACE</p><h1 id="title">Sign in</h1><p id="intro">Use Google to continue to FleetDesk.</p>
<div id="googleBox" hidden><a class="google" href="api/google-auth.php?action=start"><span class="google-mark">G</span>Continue with Google</a></div>
<div id="legacyBox" hidden><form id="loginForm"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required><button id="submit" type="submit">Sign in</button></form></div>
<div id="message" role="status" aria-live="polite"></div><p class="foot">Accounts and access roles are managed by your FleetDesk administrator.</p></main>
<script>
(async()=>{const msg=document.getElementById('message');const params=new URLSearchParams(location.search);const errors={session_expired:'You were signed out after being inactive. Sign in again to continue.',not_configured:'Google sign-in is not configured yet. Ask an App Controller to complete the Google setup.',domain:'This Google account does not meet the sign-in domain requirement.',account_conflict:'This Google account is already linked to a different FleetDesk account. Contact your App Controller.',inactive:'This FleetDesk account is disabled. Contact your App Controller.',state:'The Google sign-in session expired or its browser cookie was not returned. Start sign-in again from the same FleetDesk address.',denied:'Google sign-in was cancelled or denied. Try again and approve the requested sign-in.',missing_code:'Google did not return a sign-in code. Start sign-in again.',token:'Google returned a code, but FleetDesk could not exchange it. Check the OAuth client secret and ensure the callback URL matches exactly.',token_verify:'Google returned a token that FleetDesk could not verify. Confirm this is a Web application OAuth client.',failed:'Google sign-in could not be completed. Check the FleetDesk server log for the failure stage or contact your App Controller.'};if(params.has('google'))msg.textContent=errors[params.get('google')]||errors.failed;try{const r=await fetch('api/google-auth.php?action=status',{cache:'no-store'});const d=await r.json();if(d.enabled){document.getElementById('googleBox').hidden=false;document.getElementById('intro').textContent=d.require_workspace_domain?'Sign in securely with your '+(d.domain||'organization')+' Google Workspace account.':'Sign in securely with your Google account.'}else{document.getElementById('legacyBox').hidden=false;document.getElementById('intro').textContent='Use your FleetDesk account to continue.'}}catch{document.getElementById('legacyBox').hidden=false}document.getElementById('loginForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=document.getElementById('submit');msg.textContent='';b.disabled=true;try{const r=await fetch('api/certificate-auth.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({action:'login',username:f.username.value.trim(),password:f.password.value})});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'Sign in failed.');location.replace(d.needs_otp?'otp.php':(d.needs_role?'welcome.php':'index.php'))}catch(err){msg.textContent=err.message||'Could not reach FleetDesk.';b.disabled=false}})})();
</script></body></html>
